{
  "microtasks": [
    {
      "id": 1,
      "description": "Define a list of search keywords and boolean operators related to social media use and teenagers (e.g., 'social media AND adolescents AND mental health').",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Search academic databases (such as Google Scholar, PubMed, or PsycINFO) using the defined keywords and download 12-15 peer-reviewed articles.",
      "prerequisites": [1]
    },
    {
      "id": 3,
      "description": "Screen the abstracts of the downloaded articles to select the 8-10 most relevant papers for the literature review.",
      "prerequisites": [2]
    },
    {
      "id": 4,
      "description": "Set up a literature matrix spreadsheet with columns for Author/Year, Methodology, Key Findings, and Limitations.",
      "prerequisites": [3]
    },
    {
      "id": 5,
      "description": "Read the selected papers and populate the literature matrix with details from each study.",
      "prerequisites": [4]
    },
    {
      "id": 6,
      "description": "Analyze the completed literature matrix to group the papers into 3 distinct thematic categories (e.g., mental health impacts, sleep disruption, social connectivity).",
      "prerequisites": [5]
    },
    {
      "id": 7,
      "description": "Draft a structured outline of the literature review section, including an introduction, the 3 thematic subsections, and a summary/gap analysis.",
      "prerequisites": [6]
    },
    {
      "id": 8,
      "description": "Write the introductory paragraph of the literature review, establishing the context, importance, and organizational structure of the section.",
      "prerequisites": [7]
    },
    {
      "id": 9,
      "description": "Draft the first thematic subsection of the literature review, synthesizing the relevant sources from the matrix.",
      "prerequisites": [7]
    },
    {
      "id": 10,
      "description": "Draft the second thematic subsection of the literature review, synthesizing the relevant sources from the matrix.",
      "prerequisites": [7]
    },
    {
      "id": 11,
      "description": "Draft the third thematic subsection of the literature review, synthesizing the relevant sources from the matrix.",
      "prerequisites": [7]
    },
    {
      "id": 12,
      "description": "Write the synthesis and gap analysis subsection, highlighting what is missing in the existing literature and how your study addresses this gap.",
      "prerequisites": [9, 10, 11]
    },
    {
      "id": 13,
      "description": "Assemble the introduction, thematic subsections, and gap analysis into a single cohesive draft, adding transitional sentences between paragraphs.",
      "prerequisites": [8, 12]
    },
    {
      "id": 14,
      "description": "Format all in-text citations and generate the reference list according to the required academic style guide (e.g., APA, MLA).",
      "prerequisites": [13]
    },
    {
      "id": 15,
      "description": "Proofread the entire draft for clarity, academic tone, flow, and grammatical correctness.",
      "prerequisites": [14]
    }
  ]
}
